function qp_scientist_max_planck_import_data() {
 return json_decode('[{"slug": "max-planck", "locale": "fa-IR", "title": "زندگی‌نامه ماکس پلانک | پدر نظریه کوانتوم", "seo_title": "زندگی‌نامه ماکس پلانک | پدر کوانتوم و ثابت پلانک", "meta_description": "زندگی‌نامه کامل ماکس پلانک از تولد 1858 تا نوبل 1918 و ثابت پلانک و قانون تابش با منابع معتبر سالم.", "focus_keyword": "زندگی‌نامه ماکس پلانک", "content_html": "<!DOCTYPE html>\\n<html lang=\\"fa-IR\\" dir=\\"rtl\\">\\n<head>\\n<meta charset=\\"UTF-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n<title>زندگی‌نامه ماکس پلانک | پدر فیزیک کوانتوم و ثابت پلانک</title>\\n<meta name=\\"description\\" content=\\"زندگی‌نامه کامل ماکس پلانک از تولد ۲۳ آوریل ۱۸۵۸ در کیل تا کشف کوانتوم ۱۴ دسامبر ۱۹۰۰، نوبل ۱۹۱۸، ثابت پلانک، ایمان، اخلاق در دوران نازی و تراژدی‌های شخصی با منابع معتبر.\\">\\n<link rel=\\"canonical\\" href=\\"https://qpedia.ir/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"fa\\" href=\\"https://qpedia.ir/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"en\\" href=\\"https://qpedia.ir/en/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"x-default\\" href=\\"https://qpedia.ir/scientists/max-planck/\\">\\n<link href=\\"https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css\\" rel=\\"stylesheet\\">\\n<style>\\n  body{font-family:Vazirmatn,Tahoma,sans-serif;line-height:2.2;font-size:17.5px;color:#1e293b;max-width:840px;margin:0 auto;padding:32px 20px;background:#fff}\\n  h1{font-size:33px;font-weight:900;line-height:1.35;margin:0 0 22px;color:#0f172a}\\n  h2{font-size:24px;font-weight:800;margin:60px 0 18px;padding-bottom:10px;border-bottom:2.5px solid #e2e8f0;color:#0f172a}\\n  h3{font-size:19px;font-weight:700;margin:34px 0 14px;color:#1e293b}\\n  p{margin:0 0 10px;text-align:justify}\\n  a{color:#1d4ed8;text-decoration:none;border-bottom:1px dotted #1d4ed8}\\n  .qpedia-lead{background:#f8fafc;border-right:5px solid #3b82f6;padding:20px 22px;border-radius:12px;margin:26px 0 34px;font-size:18px}\\n  .qpedia-infobox{border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.06);margin:30px 0}\\n  .qpedia-infobox h3{margin:0;padding:14px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0}\\n  .qpedia-infobox th{text-align:right;padding:11px 20px;background:#fcfcfd;border-bottom:1px solid #f1f5f9;width:150px;font-weight:700;color:#475569;font-size:14px}\\n  .qpedia-infobox td{padding:11px 20px;border-bottom:1px solid #f1f5f9;font-size:14.5px}\\n  .table-wrapper{overflow-x:auto;border:1px solid #e5e7eb;border-radius:10px;margin:22px 0}\\n  .table-wrapper table{width:100%;min-width:560px;border-collapse:collapse;font-size:14.5px}\\n  .table-wrapper th{background:#f8fafc;padding:12px;border-bottom:2px solid #e2e8f0;text-align:right}\\n  .table-wrapper td{padding:11px 12px;border-bottom:1px solid #f1f5f9}\\n  .qpedia-quote{border-right:5px solid #10b981;background:#f0fdf4;padding:18px 22px;border-radius:12px;margin:30px 0;font-style:italic;font-size:17px}\\n  .qpedia-newspaper{border:1px dashed #d97706;background:#fffbeb;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-media{border:1px solid #e2e8f0;background:#f8fafc;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-faq{background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:24px;margin:30px 0}\\n  .qpedia-faq-item{margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #e2e8f0}\\n  .qpedia-faq-item:last-child{border:none;margin:0;padding:0}\\n  .qpedia-faq-q{font-weight:800;margin-bottom:8px}\\n  .disclaimer{background:#fef2f2;border-right:5px solid #ef4444;padding:12px 16px;border-radius:10px;font-size:13.5px;color:#57534e;margin:12px 0 20px}\\n  .author-box{background:#f1f5f9;padding:14px 18px;border-radius:10px;font-size:13.5px;margin:24px 0;border:1px solid #e2e8f0}\\n  .qpedia-para-source{font-size:12px;color:#94a3b8;margin:-4px 0 22px;line-height:1.7}\\n  .qpedia-para-source a{color:#94a3b8;border-bottom:1px dotted #cbd5e1;text-decoration:none}\\n  .qpedia-para-source a:hover{color:#64748b}\\n  @media(max-width:640px){body{padding:20px 14px;font-size:15.5px}h1{font-size:26px}h2{font-size:20px}.qpedia-infobox th{width:110px}}\\n</style>\\n</head>\\n<body>\\n\\n<h1>زندگی‌نامه ماکس پلانک | پدر فیزیک کوانتوم</h1>\\n\\n<div class=\\"author-box\\">\\n<strong>نویسنده:</strong> تحریریه Qpedia — بازبینی علمی دکتر فیزیک نظری (شریف) — <strong>انتشار:</strong> 2026-09-21 — <strong>بروزرسانی:</strong> 2026-09-21 — <a href=\\"https://qpedia.ir/about/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">درباره ما</a> | <a href=\\"https://qpedia.ir/contact/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">تماس</a>\\n</div>\\n\\n<div class=\\"qpedia-lead\\">\\nماکس پلانک مردی محافظه‌کار بود که ناخواسته فیزیک را از نو ساخت. او نمی‌خواست جهان را تکه‌تکه کند، اما وقتی داده‌های تابش جسم سیاه با هیچ فرمول کلاسیکی جور درنیامد، جسارت کرد و گفت انرژی بسته‌بسته است. همین جمله کوتاه، ۱۴ دسامبر ۱۹۰۰، تولد فیزیک کوانتوم شد و بعدها تمام فناوری مدرن از ترانزیستور تا MRI را ممکن کرد.\\n</div>\\n\\n\\n\\n<div class=\\"qpedia-infobox\\">\\n<h3>شناسنامه سریع</h3>\\n<table>\\n<tr><th>نام کامل</th><td>Max Karl Ernst Ludwig Planck — در کودکی Marx نامیده می‌شد</td></tr>\\n<tr><th>تولد</th><td>۲۳ آوریل ۱۸۵۸ — کیل، دوک‌نشین هولشتاین، آلمان</td></tr>\\n<tr><th>وفات</th><td>۴ اکتبر ۱۹۴۷ — گوتینگن، آلمان، ۸۹ ساله</td></tr>\\n<tr><th>کشور تولد</th><td>آلمان</td></tr>\\n<tr><th>کشور تحصیل</th><td>آلمان — دانشگاه مونیخ و دانشگاه برلین</td></tr>\\n<tr><th>معروف به</th><td>ثابت پلانک h، قانون تابش جسم سیاه، بنیان‌گذار نظریه کوانتوم</td></tr>\\n<tr><th>جایزه شاخص</th><td>نوبل فیزیک ۱۹۱۸ برای کشف کوانتوم انرژی</td></tr>\\n<tr><th>عقیده</th><td>لوتری، خادم کلیسا در برلین، بعدها دیدگاه دئیستی — «به خدای شخصی باور ندارم» در نامه ۱۹۴۷</td></tr>\\n</table>\\n</div>\\n\\n<h2>کودکی در کیل: خانواده‌ای از حقوق و الهیات</h2>\\n<p>ماکس پلانک در ۲۳ آوریل ۱۸۵۸ در شهر بندری کیل به دنیا آمد. خانواده‌اش از طبقه فرهیخته آلمان شمالی بودند؛ پدرش یوهان یولیوس ویلهلم پلانک استاد حقوق در دانشگاه کیل و بعد مونیخ بود و پدربزرگ و جد پدری‌اش هر دو استاد الهیات در گوتینگن بودند. این پیشینه باعث شد در خانه پلانک‌ها سه چیز همیشه حاضر باشد: احترام به قانون، نظم پروتستانی و عشق به موسیقی. خود پلانک بعدها نوشت که خانه‌شان به درستکاری، وظیفه‌شناسی و سخاوت معروف بود و همین ارزش‌ها تا پایان عمر همراهش ماند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Max Planck biography</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Planck</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize 1918 biographical</a></div>\\n\\n<p>وقتی ماکس ۹ ساله بود، خانواده به مونیخ نقل مکان کرد و او وارد ژیمنازیوم ماکسیمیلیان شد، یکی از سخت‌گیرترین مدارس باواریا. آنجا معلمی به نام هرمان مولر برای اولین بار قانون بقای انرژی را با چنان شور و شوقی توضیح داد که پلانک بعدها گفت همان لحظه فهمید فیزیک باید حرفه‌اش باشد. او شاگردی آرام و بسیار منظم بود، نمره‌های عالی می‌گرفت، پیانو را در سطح کنسرت می‌نواخت و حتی مدتی بین موسیقی و فیزیک مردد بود. در نهایت فیزیک را انتخاب کرد چون حس می‌کرد موسیقی را می‌توان به عنوان دوست داشت، اما فیزیک را باید به عنوان سرنوشت زیست.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – early life and education</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – childhood</a></div>\\n\\n<p>نکته جالب درباره نامش این است که در شناسنامه «مارکس» ثبت شده بود، نامی رایج در خانواده، اما از حدود ده سالگی خودش را «ماکس» امضا کرد و همه تا پایان عمر همین را پذیرفتند. این تغییر کوچک نشان می‌دهد از کودکی می‌خواست هویت مستقل و ساده‌تری داشته باشد، چیزی که بعدها در سبک علمی‌اش هم دیده شد: ساده کردن مسائل پیچیده تا حد یک ثابت جهانی.</p>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – name Marx to Max</a></div>\\n\\n<h2>تحصیلات: از مونیخ تا برلین و ناامیدی از استادان بزرگ</h2>\\n<p>پلانک پاییز ۱۸۷۴ وارد دانشگاه مونیخ شد. انتظار داشت از فیلیپ فون یولی، فیزیکدان معروف آن زمان، الهام بگیرد، اما یولی به او گفت فیزیک تقریبا تمام شده و فقط چند حفره کوچک مانده که پر کردن‌شان ارزش ندارد. این جمله، که بعدها به صورت افسانه در کتاب‌ها نقل شد، پلانک را دلسرد نکرد؛ برعکس، او را به سمت ترمودینامیک کشاند، شاخه‌ای که به نظرش بنیادی‌ترین قوانین طبیعت را در خود داشت. او کتاب‌های رودولف کلاوزیوس را خودخوان و با وسواس خواند و عاشق مفهوم آنتروپی شد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – University of Munich</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – thermodynamics studies</a></div>\\n\\n<p>برای تنوع، سال تحصیلی ۱۸۷۷-۱۸۷۸ را در برلین گذراند، جایی که هرمان فون هلمهولتز و گوستاو کیرشهف تدریس می‌کردند. او امیدوار بود در پایتخت علمی آلمان جرقه‌ای ببیند، اما بعدها نوشت کلاس‌هایشان را خشک و بدون الهام یافت. با این حال، همین دوره به او یاد داد که پیشرفت واقعی در فیزیک نه از سخنرانی‌های پرزرق و برق، بلکه از کار آرام و دقیق روی مسائل بنیادی می‌آید. دکترای خود را در ژوئیه ۱۸۷۹ در مونیخ، در ۲۱ سالگی، با رساله‌ای درباره قانون دوم ترمودینامیک گرفت و یک سال بعد هابلیتیشن را هم همانجا به پایان رساند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Berlin and doctorate 1879</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – PhD 1879 second law</a></div>\\n\\n<p>مسیر شغلی‌اش کند اما پیوسته بود: ۱۸۸۵ استاد فوق‌العاده در کیل شد، ۱۸۸۹ به عنوان جانشین کیرشهف به برلین دعوت شد و تا بازنشستگی در ۱۹۲۸ همانجا ماند. در برلین حلقه‌ای از شاگردان نابغه دورش جمع شد؛ از جمله ماکس فون لائوه، والتر نرنست، و بعدها ورنر هایزنبرگ و ولفگانگ پاولی که هر دو نوبل گرفتند. پلانک معلمی سخت‌گیر اما بسیار حمایت‌گر بود و از اولین کسانی بود که نسبیت خاص اینشتین در ۱۹۰۵ را جدی گرفت و برایش کلکویوم گذاشت.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – professor Kiel 1885, Berlin 1889</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – mentorship Heisenberg Pauli</a></div>\\n\\n<h2>نقطه جوش: وقتی جسم سیاه فیزیک را دو تکه کرد</h2>\\n<p>دهه ۱۸۹۰ برای پلانک دهه وسواس روی یک مسئله بود: تابش جسم سیاه. آزمایشگاه‌های برلین به رهبری هاینریش روبنس و فردیناند کورلباوم دقیق‌ترین داده‌های طیفی را اندازه گرفته بودند و نشان می‌دادند قانون وین در طول‌موج‌های بلند شکست می‌خورد، در حالی که قانون ریلی-جینز در طول‌موج‌های کوتاه به بی‌نهایت واگرا می‌شد، چیزی که بعدها «فاجعه فرابنفش» نام گرفت. پلانک که از نظر شخصیتی محافظه‌کار و بیزار از جهش‌های بی‌دلیل بود، ماه‌ها تلاش کرد با ترمودینامیک کلاسیک فرمولی درون‌یابی بسازد که هر دو حد را پوشش دهد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – Max Planck and beginnings of quantum theory, Rev. Mod. Phys. 34</a> | <a href=\\"https://www.britannica.com/science/ultraviolet-catastrophe\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – ultraviolet catastrophe</a></div>\\n\\n<p>۱۹ اکتبر ۱۹۰۰ او فرمول معروفش را به انجمن فیزیک آلمان ارائه کرد: فرمولی که با داده‌های روبنس با دقت خیره‌کننده‌ای جور بود، اما هیچ اشتقاق نظری نداشت. خود پلانک می‌دانست این کافی نیست. به گفته خودش، هفته‌های بعد «سخت‌ترین کار عمرم» را انجام داد تا مبنایی برای فرمول پیدا کند. سرانجام در ۱۴ دسامبر ۱۹۰۰، در همان انجمن، ایده‌ای را مطرح کرد که خودش آن را «از سر استیصال» خواند: برای به دست آوردن قانون درست، باید فرض کرد انرژی نوسانگرهای داخل جسم سیاه نمی‌تواند هر مقداری داشته باشد، بلکه باید مضرب صحیحی از یک مقدار پایه باشد، E = n h ν. این h یک ثابت جدید بود، بسیار کوچک، که بعدها ثابت پلانک نام گرفت. آن روز، بدون آنکه خود پلانک بخواهد، فیزیک کوانتوم متولد شد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – On the law of distribution of energy, Annalen der Physik 309</a> | <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – 14 Dec 1900 quantum hypothesis</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – birth of quantum 1900</a></div>\\n\\n<h2>سه دستاوردی که جهان را عوض کرد</h2>\\n\\n<h3>۱. قانون تابش پلانک و حل فاجعه فرابنفش</h3>\\n<p>قانون پلانک می‌گوید چگالی انرژی تابشی در فرکانس ν و دمای T برابر است با u(ν,T) = (8πhν³/c³) / (exp(hν/kT)-1). این فرمول ساده هم در فرکانس‌های کم به قانون ریلی-جینز می‌رسد و هم در فرکانس‌های زیاد به قانون وین، و از واگرایی بی‌نهایت جلوگیری می‌کند. اهمیت فلسفی‌اش این بود که برای اولین بار نشان داد طبیعت در مقیاس کوچک گسسته است، نه پیوسته. پلانک خودش سال‌ها این گسستگی را فقط یک «حیله ریاضی» می‌دید و امیدوار بود بعدا بتوان آن را به دامان فیزیک کلاسیک برگرداند، اما اینشتین در ۱۹۰۵ با توضیح اثر فوتوالکتریک نشان داد که خود نور هم بسته‌بسته است و راه برگشتی وجود ندارد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 Annalen</a> | <a href=\\"https://www.britannica.com/science/Plancks-radiation-law\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Planck\'s radiation law</a> | <a href=\\"https://doi.org/10.1002/andp.19053220806\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905 photoelectric – Annalen</a></div>\\n\\n<h3>۲. ثابت پلانک h — کوچک‌ترین کنش ممکن</h3>\\n<p>ثابت پلانک h امروز به عنوان یکی از هفت ثابت تعریف‌کننده سیستم SI، دقیقا برابر 6.62607015×10⁻³⁴ ژول‌ثانیه تعریف شده است. این عدد کوانتوم کنش است، یعنی کوچک‌ترین مقدار کنشی که طبیعت اجازه می‌دهد. پلانک در اولین تخمینش در ۱۹۰۰ مقداری حدود 6.55×10⁻²⁷ erg·s به دست آورد که با مقدار امروزی فقط چند درصد اختلاف داشت، و همزمان ثابت بولتزمن k را هم با دقت خوبی محاسبه کرد. او سپس از ترکیب h، سرعت نور c و ثابت گرانش G واحدهای طبیعی پلانک را ساخت؛ واحدهایی که امروز در کیهان‌شناسی کوانتومی و نظریه ریسمان به عنوان مقیاس‌های بنیادی جهان به کار می‌روند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA 2019 – Planck constant exact</a> | <a href=\\"https://www.britannica.com/science/Plancks-constant\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Planck constant</a> | <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – first estimate h</a></div>\\n\\n<h3>۳. معلم نسل‌ها و حامی نسبیت</h3>\\n<p>شاید کم‌تر کسی بداند که بدون حمایت پلانک، اینشتین ممکن بود سال‌ها در اداره ثبت اختراع بماند. پلانک از ۱۹۰۶ به بعد مقالات نسبیت را در سمینارهای برلین تدریس کرد، در ۱۹۱۳ همراه با نرنست شخصا به زوریخ رفت تا اینشتین را برای استادی برلین راضی کند و در ۱۹۱۴ او را به عضویت آکادمی پروس درآورد. او بین ۱۹۱۳ تا ۱۹۱۴ رئیس دانشگاه برلین و بین ۱۹۳۰ تا ۱۹۳۷ رئیس انجمن قیصر ویلهلم (امروز انجمن ماکس پلانک) بود؛ نهادی که امروز با ۸۳ موسسه بزرگ‌ترین سازمان پژوهش‌های بنیادی آلمان است. شاگردان مستقیمش مثل هایزنبرگ، پاولی و فون لائوه هر کدام فیزیک قرن بیستم را تکان دادند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – support for Einstein, rector</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Max Planck Society – history 83 institutes</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – mentorship</a></div>\\n\\n<h2>ویترین افتخارات</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>سال</th><th>جایزه</th><th>دلیل</th></tr>\\n<tr><td>۱۹۱۸ (اهدا ۱۹۱۹)</td><td>نوبل فیزیک</td><td>کشف کوانتوم انرژی و قانون تابش</td></tr>\\n<tr><td>۱۹۱۵</td><td>پور لو مریت</td><td>نشان لیاقت علمی پروس</td></tr>\\n<tr><td>۱۹۲۷</td><td>مدال لورنتس</td><td>آکادمی سلطنتی هلند</td></tr>\\n<tr><td>۱۹۲۹</td><td>مدال کاپلی</td><td>انجمن سلطنتی لندن</td></tr>\\n<tr><td>۱۹۴۵</td><td>جایزه گوته</td><td>خدمات فرهنگی</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918 – Planck</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – awards Copley Lorentz</a></div>\\n\\n<h2>پشت معادله‌ها: عشق، ایمان و تراژدی‌های پیاپی</h2>\\n<p>پلانک در ۱۸۸۷ با ماری مرک، دختر یک بانکدار مونیخی، ازدواج کرد و صاحب چهار فرزند شد: کارل (۱۸۸۸)، دوقلوهای اما و گرته (۱۸۸۹) و اروین (۱۸۹۳). زندگی خانوادگی‌اش در ابتدا آرام بود، اما از ۱۹۰۹ به بعد به تراژدی‌ای بی‌پایان تبدیل شد. ماری در ۱۹۰۹ احتمالا بر اثر سل درگذشت، کارل در ۱۹۱۶ در نبرد وردن در جنگ جهانی اول کشته شد، گرته در ۱۹۱۷ هنگام زایمان اول و اما در ۱۹۱۹ به همان شکل درگذشت. پلانک در ۱۹۱۱ با مارگا فون هسلین ازدواج کرد و پسری به نام هرمان (۱۹۱۱-۱۹۵۴) به دنیا آمد، اما سایه مرگ همچنان همراهش بود.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – family Marie Merck, children</a> | <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor\'s Paradise – personal tragedies</a></div>\\n\\n<p>از نظر شخصیتی، همه او را به درستکاری وسواسی، وفاداری و عشق به موسیقی می‌شناختند. او هر روز پیانو می‌نواخت، با اینشتین دوئت ویولن-پیانو اجرا می‌کرد و معتقد بود موسیقی نظم کیهانی را به انسان نشان می‌دهد. شاگردانش می‌گفتند در کلاس بسیار دقیق و شمرده درس می‌دهد، هیچ‌وقت غیبت نمی‌کند و حتی در سخت‌ترین سال‌های جنگ جهانی اول هم کلاس‌هایش را تعطیل نکرد. همین روحیه وظیفه‌شناسی بعدها در دوران نازیسم برایش گران تمام شد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – character, music lover</a></div>\\n\\n<h2>ایمان و شک: از خادم کلیسا تا نامه ۱۹۴۷</h2>\\n<p>پلانک در خانواده‌ای لوتری بزرگ شد و در برلین سال‌ها نقش خادم کلیسا (Kirchenältester) را داشت، نقشی شبیه دستیار کشیش در امور اجتماعی کلیسا. او در سخنرانی معروف «دین و علوم طبیعی» در ۱۹۳۷ گفت: «هرگز نمی‌تواند تضاد واقعی بین دین و علم وجود داشته باشد، زیرا یکی مکمل دیگری است». این جمله بعدها بارها نقل شد. اما در نامه‌ای خصوصی در ۱۸ ژوئن ۱۹۴۷ به دوستش کیک نوشت: «من عمیقا مذهبی‌ام، اما به خدای شخصی و مسیحی باور ندارم». مورخان امروز او را بیشتر دئیست می‌دانند؛ کسی که به نظم اخلاقی جهان باور داشت، اما نه به خدایی که در دعاهای روزمره دخالت کند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.archiv-berlin.mpg.de/201046/Max-Planck-und-ein-zweifelhaftes-Zitat\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG Archive Berlin – Planck religion letter 1947</a> | <a href=\\"https://enlightenedcrowd.org/max-plancks-religion-church-elder-deist/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Enlightened Crowd – church elder role</a> | <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – Religion and Natural Science 1937</a></div>\\n\\n<h2>بین وظیفه و وجدان: سال‌های ۱۹۳۳ تا ۱۹۴۵</h2>\\n<p>وقتی هیتلر در ژانویه ۱۹۳۳ به قدرت رسید، بسیاری از دانشمندان آلمان را ترک کردند، اما پلانک ۷۵ ساله ماند. او فکر می‌کرد اگر بماند می‌تواند از داخل از علم آلمان محافظت کند. در بهار ۱۹۳۳ شخصا با هیتلر دیدار کرد تا برای همکاران یهودی‌اش مثل فریتس هابر و اینشتین وساطت کند. دیدار فاجعه‌بار بود؛ هیتلر عصبانی شد و گفت یهودیان همه کمونیست‌اند. پلانک بعدها نوشت که آن لحظه فهمید منطق با آن رژیم کار نمی‌کند. او با این حال از اخراج‌ها انتقاد علنی کرد، از انجمن قیصر ویلهلم استعفا داد و در ۱۹۳۷ تحت فشار نازی‌ها مجبور به کناره‌گیری شد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor\'s Paradise – meeting Hitler 1933</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Nazi period, resignation 1937</a></div>\\n\\n<p>سخت‌ترین ضربه در ژانویه ۱۹۴۵ آمد. پسرش اروین پلانک که افسر سابق و سیاستمدار میانه‌رو بود، به اتهام مشارکت در توطئه ۲۰ ژوئیه برای ترور هیتلر بازداشت و در ۲۳ ژانویه ۱۹۴۵ در زندان پلوتزنزه اعدام شد. پلانک که در آن زمان ۸۶ ساله بود و خانه‌اش در بمباران ۱۹۴۴ ویران شده بود، در نامه‌ای نوشت: «بزرگ‌ترین درد زندگی‌ام را می‌کشم». او دو سال بعد، در ۴ اکتبر ۱۹۴۷ در گوتینگن درگذشت و در همان شهر به خاک سپرده شد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://historydraft.com/story/max-planck/erwin-his-son-was-hanged/304/1909\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Historydraft – Erwin Planck executed 23 Jan 1945</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – house destroyed 1944, death 1947</a></div>\\n\\n<h2>روایت‌هایی که می‌گویند — با مهر «سند قطعی ندارد»</h2>\\n<p>یکی از معروف‌ترین روایت‌ها این است که فون یولی به پلانک جوان گفت فیزیک تمام شده و بهتر است سراغ رشته دیگری برود. این داستان در خاطرات بسیاری از فیزیکدانان آمده و حتی در کتاب‌های درسی چاپ شده، اما هیچ نامه‌ای از یولی با همین جمله پیدا نشده است. به نظر می‌رسد یولی واقعا نسبت به آینده فیزیک بدبین بود، اما جمله دقیق «فیزیک تمام شده» بیشتر یک بازسازی شفاهی از خاطرات شاگردان است تا یک نقل قول مستند.</p>\\n<div class=\\"disclaimer\\">این روایت در خاطرات شاگردان آمده اما سند مکتوب معاصر با همین جمله وجود ندارد — به عنوان سنت شفاهی نقل می‌شود.</div>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – von Jolly anecdote discussion</a></div>\\n\\n<p>روایت دیگر جمله معروف پلانک است: «حقیقت جدید علمی با متقاعد کردن مخالفان پیروز نمی‌شود، بلکه با مرگ آن‌ها و رشد نسلی جدید که از ابتدا با آن آشناست پیروز می‌شود». این جمله با کمی تفاوت در خودزندگی‌نامه علمی او در ۱۹۴۹ آمده و به «اصل پلانک» معروف شده است. جامعه‌شناسان علم امروز آن را اغراق‌آمیز می‌دانند، اما هسته‌اش درست است: پذیرش ایده‌های انقلابی اغلب یک نسل طول می‌کشد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – Scientific Autobiography 1949 Planck principle</a></div>\\n\\n<h2>در یک نگاه: جمله‌ای که ماند</h2>\\n<div class=\\"qpedia-quote\\">\\n«یک حقیقت علمی جدید با متقاعد کردن مخالفانش پیروز نمی‌شود، بلکه مخالفانش کم‌کم می‌میرند و نسلی جدید که از ابتدا با آن آشناست رشد می‌کند.» — ماکس پلانک، خودزندگی‌نامه علمی، ۱۹۴۹\\n</div>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – Max Planck 1949</a></div>\\n\\n<h2>روزنامه‌های آن زمان چه نوشتند؟</h2>\\n<div class=\\"qpedia-newspaper\\">\\n📰 انجمن فیزیک آلمان — ۱۴ دسامبر ۱۹۰۰: «آقای پلانک درباره قانون توزیع انرژی گزارش می‌دهد.» این گزارش کوتاه بعدها در Annalen der Physik ۱۹۰۱ با عنوان «درباره قانون توزیع انرژی در طیف نرمال» منتشر شد و امروز به عنوان شناسنامه فیزیک کوانتوم شناخته می‌شود.\\n</div>\\n<div class=\\"qpedia-para-source\\">منبع: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – Annalen der Physik</a></div>\\n\\n<h2>بازتاب امروز</h2>\\n<div class=\\"qpedia-media\\">\\n🔬 وقتی در ۲۰۱۹ سیستم SI بازتعریف شد، کیلوگرم دیگر با یک استوانه فلزی تعریف نشد، بلکه با ثابت پلانک h تعریف شد. یعنی از آن به بعد، هر ترازویی در جهان به طور غیرمستقیم با کشف ۱۹۰۰ پلانک کار می‌کند. این شاید بزرگ‌ترین میراث عملی او باشد: تبدیل یک ثابت آزمایشگاهی به پایه‌ای برای اندازه‌گیری جهان.\\n</div>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA – Planck constant SI 2019 redefinition</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Max Planck Society – legacy</a></div>\\n\\n<h2>میراث او در جیب شما</h2>\\n<p>اگر امروز از گوشی‌ات استفاده می‌کنی، مدیون پلانک هستی. ترانزیستور که قلب گوشی است بدون کوانتوم قابل توضیح نیست، لیزر که اینترنت فیبر نوری را می‌سازد از گذارهای کوانتیده‌ای استفاده می‌کند که پلانک اولین بار توصیف کرد، و ساعت اتمی که GPS را دقیق می‌کند با فرکانس‌هایی کار می‌کند که مضرب h هستند. حتی دماسنج‌های فروسرخ پزشکی و مدل‌های اقلیمی که گرمایش زمین را پیش‌بینی می‌کنند، از قانون تابش پلانک استفاده می‌کنند. انجمن ماکس پلانک امروز با ۸۳ موسسه در آلمان و جهان، همان روحیه «علم برای شناخت» را ادامه می‌دهد که پلانک عمرش را وقف آن کرد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/science/Plancks-constant\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – applications transistor laser</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG – 83 institutes</a></div>\\n\\n<h2>خط زمان دقیق</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>تاریخ</th><th>رویداد</th></tr>\\n<tr><td>۱۸۵۸-۰۴-۲۳</td><td>تولد در کیل، آلمان</td></tr>\\n<tr><td>۱۸۷۴</td><td>ورود به دانشگاه مونیخ</td></tr>\\n<tr><td>۱۸۷۹-۰۷</td><td>دکترا در ۲۱ سالگی، قانون دوم ترمودینامیک</td></tr>\\n<tr><td>۱۸۸۹</td><td>استاد برلین، جانشین کیرشهف</td></tr>\\n<tr><td>۱۹۰۰-۱۲-۱۴</td><td>معرفی کوانتوم انرژی E=hν در انجمن فیزیک آلمان</td></tr>\\n<tr><td>۱۹۱۸</td><td>نوبل فیزیک</td></tr>\\n<tr><td>۱۹۳۳</td><td>دیدار با هیتلر برای دفاع از دانشمندان یهودی</td></tr>\\n<tr><td>۱۹۴۵-۰۱-۲۳</td><td>اعدام پسر اروین به اتهام توطئه ۲۰ ژوئیه</td></tr>\\n<tr><td>۱۹۴۷-۱۰-۰۴</td><td>وفات در گوتینگن</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – timeline</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918 timeline</a> | <a href=\\"https://historydraft.com/story/max-planck/erwin-his-son-was-hanged/304/1909\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Historydraft – Erwin 1945</a></div>\\n\\n<h2>چهار سوءتفاهم رایج</h2>\\n<p><strong>۱. پلانک عاشق کوانتوم بود.</strong> نه، خودش آن را «از سر استیصال» خواند و سال‌ها امیدوار بود بتوان آن را به فیزیک کلاسیک برگرداند. این اینشتین بود که کوانتوم را جدی گرفت.</p>\\n<p><strong>۲. پلانک ضد دین بود.</strong> نه، او خادم کلیسا بود و معتقد بود دین و علم مکمل‌اند، اما به خدای شخصی باور نداشت.</p>\\n<p><strong>۳. با نازی‌ها همکاری کرد.</strong> نه، او در آلمان ماند تا از موسسات علمی محافظت کند، با هیتلر برای یهودیان دیدار کرد و طرد شد، و در ۱۹۳۷ استعفا داد.</p>\\n<p><strong>۴. ثابت پلانک را دقیق اندازه گرفت.</strong> مقدار اولیه‌اش تقریبی بود؛ مقدار دقیق امروزی از تعریف SI در ۲۰۱۹ می‌آید.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – act of desperation</a> | <a href=\\"https://www.archiv-berlin.mpg.de/201046/Max-Planck-und-ein-zweifelhaftes-Zitat\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG Archive – religion</a> | <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor – Nazi period</a> | <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA – exact h</a></div>\\n\\n<h2>جمع‌بندی: مردی که جهان را بسته‌بسته دید</h2>\\n<p>ماکس پلانک در ۲۳ آوریل ۱۸۵۸ در کیل متولد شد، در ۱۴ دسامبر ۱۹۰۰ با یک فرض به ظاهر کوچک فیزیک را دو تکه کرد، در ۱۹۱۸ نوبل گرفت، در سخت‌ترین سال‌های آلمان ماند تا از علم دفاع کند، چهار فرزند و خانه‌اش را از دست داد و در ۴ اکتبر ۱۹۴۷ در گوتینگن درگذشت. ثابت کوچک او، h، امروز در هر تراشه، هر لیزر و هر ساعت اتمی حضور دارد و به ما یادآوری می‌کند که گاهی بزرگ‌ترین انقلاب‌ها از محافظه‌کارترین ذهن‌ها می‌آیند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Max Planck overview</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918</a></div>\\n\\n<h2>پرسش‌های متداول</h2>\\n<div class=\\"qpedia-faq\\">\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">ماکس پلانک کیست؟</div><div>فیزیکدان آلمانی که در ۱۴ دسامبر ۱۹۰۰ با فرض E=hν کوانتوم انرژی را معرفی کرد و به عنوان پدر فیزیک کوانتوم شناخته می‌شود و نوبل ۱۹۱۸ را گرفت.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">ثابت پلانک چیست؟</div><div>h = 6.62607015×10⁻³⁴ ژول‌ثانیه، کوچک‌ترین کنش ممکن در طبیعت که از ۲۰۱۹ به صورت دقیق تعریف شده و پایه تعریف کیلوگرم است.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">آیا پلانک مذهبی بود؟</div><div>لوتری و خادم کلیسا بود، اما در نامه ۱۹۴۷ نوشت به خدای شخصی باور ندارد؛ مورخان او را دئیست می‌دانند.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">چه تراژدی‌هایی داشت؟</div><div>همسر اول ۱۹۰۹، پسر کارل ۱۹۱۶ در وردن، دختران گرته ۱۹۱۷ و اما ۱۹۱۹ در زایمان، پسر اروین ۱۹۴۵ اعدام توسط نازی‌ها.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">میراث امروز چیست؟</div><div>انجمن ماکس پلانک با ۸۳ موسسه، و پایه تمام فناوری کوانتومی از ترانزیستور تا GPS و MRI.</div></div>\\n</div>\\n\\n<h2>منابع و مطالعه بیشتر</h2>\\n<ol>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Max Planck biographical 1918</a></li>\\n<li><a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Max Planck biography</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – Annalen der Physik 309: 553-563</a></li>\\n<li><a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Max Planck</a></li>\\n<li><a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA – Planck constant exact 2019</a></li>\\n<li><a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – Max Planck and beginnings of quantum theory, Rev. Mod. Phys. 34</a></li>\\n</ol>\\n\\n<div class=\\"qpedia-internal\\">\\n<strong>در Qpedia بیشتر بخوان:</strong> <a href=\\"https://qpedia.ir/what-is-quantum/\\">کوانتوم چیست</a> | <a href=\\"https://qpedia.ir/ultraviolet-catastrophe/\\">فاجعه فرابنفش</a> | <a href=\\"https://qpedia.ir/planck-constant/\\">ثابت پلانک</a> | <a href=\\"https://qpedia.ir/scientists/albert-einstein/\\">آلبرت اینشتین</a> | <a href=\\"https://qpedia.ir/scientists/niels-bohr/\\">نیلز بور</a>\\n</div>\\n\\n<script type=\\"application/ld+json\\">\\n{\\n  \\"@context\\":\\"https://schema.org\\",\\n  \\"@graph\\":[\\n    {\\"@type\\":\\"Person\\",\\"@id\\":\\"https://qpedia.ir/scientists/max-planck/#person\\",\\"name\\":\\"Max Planck\\",\\"alternateName\\":\\"ماکس پلانک\\",\\"birthDate\\":\\"1858-04-23\\",\\"deathDate\\":\\"1947-10-04\\",\\"birthPlace\\":{\\"@type\\":\\"Place\\",\\"name\\":\\"Kiel, Germany\\"},\\"nationality\\":\\"German\\",\\"award\\":[\\"Nobel Prize in Physics 1918\\"],\\"sameAs\\":[\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\",\\"https://www.britannica.com/biography/Max-Planck\\",\\"https://doi.org/10.1002/andp.19013090310\\"],\\"image\\":\\"https://qpedia.ir/wp-content/uploads/max-planck.webp\\"},\\n    {\\"@type\\":\\"Article\\",\\"headline\\":\\"زندگی‌نامه ماکس پلانک | پدر فیزیک کوانتوم و ثابت پلانک\\",\\"inLanguage\\":\\"fa-IR\\",\\"about\\":{\\"@id\\":\\"https://qpedia.ir/scientists/max-planck/#person\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Qpedia\\"},\\"datePublished\\":\\"2026-09-21\\",\\"dateModified\\":\\"2026-09-21\\"},\\n    {\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"خانه\\",\\"item\\":\\"https://qpedia.ir/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"دانشمندان\\",\\"item\\":\\"https://qpedia.ir/scientists/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"ماکس پلانک\\",\\"item\\":\\"https://qpedia.ir/scientists/max-planck/\\"}]},\\n    {\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"ماکس پلانک کیست؟\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"فیزیکدان آلمانی که 1900 کوانتوم انرژی را معرفی کرد.\\"}}]}\\n  ]\\n}\\n</script>\\n\\n</body>\\n</html>\\n", "canonical": "https://qpedia.ir/scientists/max-planck/", "hreflang_en": "https://qpedia.ir/en/scientists/max-planck/", "hreflang_fa": "https://qpedia.ir/scientists/max-planck/", "old_slugs": ["max-plank"], "status": "publish", "post_type": "quantum_scientist"}, {"slug": "max-planck-en", "locale": "en-US", "title": "Max Planck Biography | Father of Quantum Theory", "seo_title": "Max Planck Biography | Quantum Constant & Nobel 1918", "meta_description": "Full biography of Max Planck: born 1858, quantum hypothesis 1900, Planck constant, Nobel 1918, verified sources.", "focus_keyword": "Max Planck biography", "content_html": "<!DOCTYPE html>\\n<html lang=\\"en-US\\" dir=\\"ltr\\">\\n<head>\\n<meta charset=\\"UTF-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n<title>Max Planck Biography | Father of Quantum Theory & Planck Constant</title>\\n<meta name=\\"description\\" content=\\"Full biography of Max Planck: born 23 April 1858 Kiel, quantum discovery 14 Dec 1900, Nobel 1918, Planck constant h, faith, ethics in Nazi era, personal tragedies with verified sources.\\">\\n<link rel=\\"canonical\\" href=\\"https://qpedia.ir/en/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"fa\\" href=\\"https://qpedia.ir/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"en\\" href=\\"https://qpedia.ir/en/scientists/max-planck/\\">\\n<link rel=\\"alternate\\" hreflang=\\"x-default\\" href=\\"https://qpedia.ir/scientists/max-planck/\\">\\n<link href=\\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap\\" rel=\\"stylesheet\\">\\n<style>\\n  body{font-family:Inter,Helvetica,Arial,sans-serif;line-height:1.95;font-size:17px;color:#1e293b;max-width:840px;margin:0 auto;padding:32px 20px;background:#fff}\\n  h1{font-size:32px;font-weight:900;line-height:1.35;margin:0 0 22px;color:#0f172a}\\n  h2{font-size:23px;font-weight:800;margin:60px 0 18px;padding-bottom:10px;border-bottom:2.5px solid #e2e8f0;color:#0f172a}\\n  h3{font-size:19px;font-weight:700;margin:34px 0 14px;color:#1e293b}\\n  p{margin:0 0 10px;text-align:left}\\n  a{color:#1d4ed8;text-decoration:none;border-bottom:1px dotted #1d4ed8}\\n  .qpedia-lead{background:#f8fafc;border-left:5px solid #3b82f6;padding:20px 22px;border-radius:12px;margin:26px 0 34px;font-size:18px}\\n  .qpedia-infobox{border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.06);margin:30px 0}\\n  .qpedia-infobox h3{margin:0;padding:14px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0}\\n  .qpedia-infobox th{text-align:left;padding:11px 20px;background:#fcfcfd;border-bottom:1px solid #f1f5f9;width:150px;font-weight:700;color:#475569;font-size:14px}\\n  .qpedia-infobox td{padding:11px 20px;border-bottom:1px solid #f1f5f9;font-size:14.5px}\\n  .table-wrapper{overflow-x:auto;border:1px solid #e5e7eb;border-radius:10px;margin:22px 0}\\n  .table-wrapper table{width:100%;min-width:560px;border-collapse:collapse;font-size:14.5px}\\n  .table-wrapper th{background:#f8fafc;padding:12px;border-bottom:2px solid #e2e8f0;text-align:left}\\n  .table-wrapper td{padding:11px 12px;border-bottom:1px solid #f1f5f9}\\n  .qpedia-quote{border-left:5px solid #10b981;background:#f0fdf4;padding:18px 22px;border-radius:12px;margin:30px 0;font-style:italic;font-size:17px}\\n  .qpedia-newspaper{border:1px dashed #d97706;background:#fffbeb;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-media{border:1px solid #e2e8f0;background:#f8fafc;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-faq{background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:24px;margin:30px 0}\\n  .qpedia-faq-item{margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #e2e8f0}\\n  .qpedia-faq-item:last-child{border:none;margin:0;padding:0}\\n  .qpedia-faq-q{font-weight:800;margin-bottom:8px}\\n  .disclaimer{background:#fef2f2;border-left:5px solid #ef4444;padding:12px 16px;border-radius:10px;font-size:13.5px;color:#57534e;margin:12px 0 20px}\\n  .author-box{background:#f1f5f9;padding:14px 18px;border-radius:10px;font-size:13.5px;margin:24px 0;border:1px solid #e2e8f0}\\n  .qpedia-para-source{font-size:12px;color:#94a3b8;margin:-4px 0 22px;line-height:1.7}\\n  .qpedia-para-source a{color:#94a3b8;border-bottom:1px dotted #cbd5e1;text-decoration:none}\\n  .qpedia-para-source a:hover{color:#64748b}\\n  @media(max-width:640px){body{padding:20px 14px;font-size:15.5px}h1{font-size:26px}h2{font-size:20px}.qpedia-infobox th{width:110px}}\\n</style>\\n</head>\\n<body>\\n\\n<h1>Max Planck Biography | Father of Quantum Theory</h1>\\n\\n<div class=\\"author-box\\">\\n<strong>Author:</strong> Qpedia Editorial — Reviewed by PhD Theoretical Physics (Sharif) — <strong>Published:</strong> 2026-09-21 — <strong>Updated:</strong> 2026-09-21 — <a href=\\"https://qpedia.ir/en/about/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">About</a> | <a href=\\"https://qpedia.ir/en/contact/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Contact</a>\\n</div>\\n\\n<div class=\\"qpedia-lead\\">\\nMax Planck was a conservative professor who accidentally split physics in two. He did not want to quantize the world, but when the blackbody data refused to fit any classical formula, he dared to say energy comes in packets. That single sentence on 14 December 1900 became the birthday of quantum physics and later made possible every modern technology from transistors to MRI.\\n</div>\\n\\n\\n\\n<div class=\\"qpedia-infobox\\">\\n<h3>Quick Facts</h3>\\n<table>\\n<tr><th>Full name</th><td>Max Karl Ernst Ludwig Planck — baptized Marx</td></tr>\\n<tr><th>Birth</th><td>23 April 1858 — Kiel, Duchy of Holstein, Germany</td></tr>\\n<tr><th>Death</th><td>4 October 1947 — Göttingen, Germany, age 89</td></tr>\\n<tr><th>Birth country</th><td>Germany</td></tr>\\n<tr><th>Education</th><td>Germany — University of Munich, University of Berlin</td></tr>\\n<tr><th>Known for</th><td>Planck constant h, blackbody radiation law, founder of quantum theory</td></tr>\\n<tr><th>Prize</th><td>Nobel Prize in Physics 1918 for discovery of energy quanta</td></tr>\\n<tr><th>Faith</th><td>Lutheran, church elder in Berlin, later deist — “I do not believe in a personal Christian God” letter 1947</td></tr>\\n</table>\\n</div>\\n\\n<h2>Childhood in Kiel: A House of Law and Theology</h2>\\n<p>Max Planck was born on 23 April 1858 in the port city of Kiel. His family belonged to the educated North German elite; his father Johann Julius Wilhelm Planck was a professor of law at Kiel and later Munich, and both his grandfather and great-grandfather were theology professors in Göttingen. This background meant three things were always present in the Planck household: respect for law, Protestant discipline, and love for music. Planck later wrote that his family was known for integrity, duty, and generosity, values that stayed with him for life.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Max Planck biography</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Planck</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918 biographical</a></div>\\n\\n<p>When Max was 9, the family moved to Munich and he entered the Maximilians Gymnasium, one of Bavaria’s strictest schools. There a teacher named Hermann Müller explained the conservation of energy with such passion that Planck later said it was the moment he knew physics must be his profession. He was a quiet, extremely orderly student, got excellent grades, played piano at concert level, and for a while hesitated between music and physics. He finally chose physics because, as he put it, music could be loved as a friend, but physics had to be lived as destiny.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – early life</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – childhood</a></div>\\n\\n<p>An interesting detail about his name is that he was registered as Marx, a common family name, but from around age ten he signed himself Max and everyone accepted it. This small change shows he wanted a simpler, independent identity from childhood, something later visible in his scientific style: simplifying complex problems down to a universal constant.</p>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – name Marx to Max</a></div>\\n\\n<h2>Education: From Munich to Berlin and Disappointment with Great Professors</h2>\\n<p>Planck entered the University of Munich in autumn 1874. He expected inspiration from Philipp von Jolly, a famous physicist of the time, but Jolly told him physics was almost complete and only a few small gaps remained, not worth pursuing. This sentence, later legendary in textbooks, did not discourage Planck; on the contrary, it pushed him toward thermodynamics, a branch he felt contained the most fundamental laws of nature. He read Rudolf Clausius’s books on his own, obsessively, and fell in love with the concept of entropy.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Munich University</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – thermodynamics</a></div>\\n\\n<p>For variety, he spent the academic year 1877-1878 in Berlin, where Hermann von Helmholtz and Gustav Kirchhoff taught. He hoped to find a spark in Germany’s scientific capital, but later wrote he found their lectures dry and uninspiring. However, this period taught him that real progress in physics comes not from flashy lectures but from quiet, precise work on fundamental problems. He received his doctorate in July 1879 in Munich, at age 21, with a thesis on the second law of thermodynamics, and completed his habilitation a year later in the same city.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Berlin and doctorate 1879</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – PhD 1879</a></div>\\n\\n<p>His career path was slow but steady: associate professor in Kiel in 1885, successor to Kirchhoff in Berlin in 1889, where he remained until retirement in 1928. In Berlin a circle of brilliant students gathered around him, including Max von Laue, Walther Nernst, and later Werner Heisenberg and Wolfgang Pauli, both future Nobel laureates. Planck was a strict but very supportive teacher and was among the first to take Einstein’s special relativity in 1905 seriously, organizing a colloquium for him.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – professor Kiel 1885 Berlin 1889</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – mentorship</a></div>\\n\\n<h2>The Boiling Point: When Blackbody Split Physics</h2>\\n<p>The 1890s were for Planck a decade of obsession with one problem: blackbody radiation. Laboratories in Berlin led by Heinrich Rubens and Ferdinand Kurlbaum had measured the most precise spectral data, showing Wien’s law failed at long wavelengths, while Rayleigh-Jeans law diverged to infinity at short wavelengths, later called the ultraviolet catastrophe. Planck, conservative by character and averse to unjustified leaps, spent months trying to build an interpolation formula from classical thermodynamics that would cover both limits.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – Max Planck and beginnings of quantum theory</a> | <a href=\\"https://www.britannica.com/science/ultraviolet-catastrophe\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – ultraviolet catastrophe</a></div>\\n\\n<p>On 19 October 1900 he presented his famous formula to the German Physical Society: a formula that matched Rubens’s data with stunning accuracy but had no theoretical derivation. Planck knew this was not enough. By his own account, the following weeks were “the hardest work of my life” to find a basis for the formula. Finally, on 14 December 1900, in the same society, he proposed an idea he himself called “an act of desperation”: to obtain the correct law, one must assume the energy of oscillators inside the blackbody cannot have any value, but must be an integer multiple of a basic amount, E = n h ν. This h was a new constant, extremely small, later named Planck’s constant. That day, without Planck wanting it, quantum physics was born.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – distribution law Annalen</a> | <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – 14 Dec 1900</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel – birth of quantum 1900</a></div>\\n\\n<h2>Three Achievements that Changed the World</h2>\\n\\n<h3>1. Planck’s Radiation Law and Solving the Ultraviolet Catastrophe</h3>\\n<p>Planck’s law says the spectral energy density at frequency ν and temperature T is u(ν,T) = (8πhν³/c³)/(exp(hν/kT)-1). This simple formula reaches Rayleigh-Jeans at low frequencies and Wien at high frequencies and avoids infinite divergence. Its philosophical importance was that for the first time it showed nature at small scales is discrete, not continuous. Planck himself for years saw this discreteness only as a mathematical trick and hoped it could be returned to classical physics, but Einstein in 1905 with the photoelectric effect showed that light itself is quantized and there was no way back.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 Annalen</a> | <a href=\\"https://www.britannica.com/science/Plancks-radiation-law\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Planck\'s law</a> | <a href=\\"https://doi.org/10.1002/andp.19053220806\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905 photoelectric</a></div>\\n\\n<h3>2. Planck Constant h — Smallest Possible Action</h3>\\n<p>Planck’s constant h is today one of seven defining constants of the SI system, exactly 6.62607015×10⁻³⁴ J·s. This number is the quantum of action, the smallest amount of action nature allows. In his first estimate in 1900 Planck obtained about 6.55×10⁻²⁷ erg·s, only a few percent off the modern value, and simultaneously calculated Boltzmann’s constant k with good accuracy. He then built Planck natural units from h, speed of light c, and gravitational constant G; units today used in quantum cosmology and string theory as fundamental scales of the universe.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA 2019 – Planck constant exact</a> | <a href=\\"https://www.britannica.com/science/Plancks-constant\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Planck constant</a> | <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – first estimate</a></div>\\n\\n<h3>3. Teacher of Generations and Champion of Relativity</h3>\\n<p>Perhaps few know that without Planck’s support, Einstein might have stayed years in the patent office. From 1906 onward Planck taught relativity in Berlin seminars, in 1913 went personally with Nernst to Zurich to convince Einstein to take a Berlin professorship, and in 1914 made him a member of the Prussian Academy. Between 1913-1914 he was rector of Berlin University and 1930-1937 president of Kaiser Wilhelm Society (today Max Planck Society); an institution today with 83 institutes, Germany’s largest basic research organization. His direct students like Heisenberg, Pauli, and von Laue each shook 20th-century physics.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – support Einstein rector</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Max Planck Society – 83 institutes</a> | <a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford – mentorship</a></div>\\n\\n<h2>Showcase of Honors</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>Year</th><th>Award</th><th>Reason</th></tr>\\n<tr><td>1918 (awarded 1919)</td><td>Nobel Prize Physics</td><td>Discovery of energy quanta and radiation law</td></tr>\\n<tr><td>1915</td><td>Pour le Mérite</td><td>Scientific merit Prussia</td></tr>\\n<tr><td>1927</td><td>Lorentz Medal</td><td>Royal Netherlands Academy</td></tr>\\n<tr><td>1929</td><td>Copley Medal</td><td>Royal Society London</td></tr>\\n<tr><td>1945</td><td>Goethe Prize</td><td>Cultural services</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – awards</a></div>\\n\\n<h2>Behind Equations: Love, Faith, and Repeated Tragedies</h2>\\n<p>In 1887 Planck married Marie Merck, daughter of a Munich banker, and had four children: Karl (1888), twins Emma and Grete (1889), and Erwin (1893). His family life was initially calm but from 1909 onward turned into endless tragedy. Marie died in 1909 probably from tuberculosis, Karl was killed in 1916 at the Battle of Verdun in World War I, Grete died in 1917 during first childbirth and Emma in 1919 the same way. Planck married Marga von Hoesslin in 1911 and had a son Hermann (1911-1954), but the shadow of death remained with him.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – family</a> | <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor\'s Paradise – personal tragedies</a></div>\\n\\n<p>Personality-wise, everyone knew him for obsessive integrity, loyalty, and love for music. He played piano daily, performed violin-piano duets with Einstein, and believed music shows cosmic order to humans. His students said he lectured very precisely and slowly, never missed a class, and even in hardest years of World War I did not cancel his courses. This sense of duty later cost him dearly in Nazi era.</p>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – character music</a></div>\\n\\n<h2>Faith and Doubt: From Church Elder to 1947 Letter</h2>\\n<p>Planck grew up Lutheran and for years served as church elder (Kirchenältester) in Berlin, a role like assistant pastor in social affairs. In his famous lecture Religion and Natural Science in 1937 he said: “There can never be any real opposition between religion and science, for the one is the complement of the other.” This sentence was later quoted widely. But in a private letter on 18 June 1947 to his friend Kick he wrote: “I am deeply religious, but I do not believe in a personal Christian God.” Historians today see him more as a deist; someone who believed in moral order of world, but not in a God who intervenes in daily prayers.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.archiv-berlin.mpg.de/201046/Max-Planck-und-ein-zweifelhaftes-Zitat\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG Archive – religion letter 1947</a> | <a href=\\"https://enlightenedcrowd.org/max-plancks-religion-church-elder-deist/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Enlightened Crowd – church elder</a> | <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – 1937 lecture</a></div>\\n\\n<h2>Between Duty and Conscience: 1933-1945</h2>\\n<p>When Hitler came to power in January 1933, many scientists left Germany, but 75-year-old Planck stayed. He thought if he stayed he could protect German science from inside. In spring 1933 he personally met Hitler to plead for Jewish colleagues like Fritz Haber and Einstein. The meeting was disastrous; Hitler became angry and said Jews are all communists. Planck later wrote that at that moment he realized logic did not work with that regime. Nevertheless he publicly criticized expulsions, resigned from Kaiser Wilhelm Society, and in 1937 was forced to resign under Nazi pressure.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor\'s Paradise – meeting Hitler 1933</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Nazi period</a></div>\\n\\n<p>The hardest blow came in January 1945. His son Erwin Planck, former officer and moderate politician, was arrested for alleged participation in 20 July plot to assassinate Hitler and executed on 23 January 1945 in Plötzensee prison. Planck, then 86, whose house had been destroyed in 1944 bombing, wrote in a letter: “I suffer the greatest pain of my life.” He died two years later, on 4 October 1947 in Göttingen and was buried there.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://historydraft.com/story/max-planck/erwin-his-son-was-hanged/304/1909\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Historydraft – Erwin executed 23 Jan 1945</a> | <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – house destroyed 1944 death 1947</a></div>\\n\\n<h2>Stories People Tell — Marked “No Official Document”</h2>\\n<p>One of most famous stories is that von Jolly told young Planck physics was complete and he should switch fields. This story appears in memoirs of many physicists and even textbooks, but no letter from Jolly with this exact sentence has been found. It seems Jolly was indeed pessimistic about future of physics, but exact phrase “physics is complete” is more an oral reconstruction from students’ memories than a documented quote.</p>\\n<div class=\\"disclaimer\\">This anecdote appears in students\' memoirs but no contemporary letter with exact wording exists — oral tradition.</div>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – von Jolly anecdote</a></div>\\n\\n<p>Another quote famous is Planck’s: “A new scientific truth does not triumph by convincing its opponents, but rather its opponents eventually die and a new generation grows up that is familiar with it.” This sentence appears with slight differences in his Scientific Autobiography in 1949 and became known as Planck’s principle. Sociologists of science today see it as exaggerated, but its core is true: acceptance of revolutionary ideas often takes a generation.</p>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – Scientific Autobiography 1949</a></div>\\n\\n<h2>At a Glance: A Sentence That Remained</h2>\\n<div class=\\"qpedia-quote\\">\\n“A new scientific truth does not triumph by convincing its opponents and making them see the light, but rather because its opponents eventually die, and a new generation grows up that is familiar with it.” — Max Planck, Scientific Autobiography, 1949\\n</div>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://en.wikiquote.org/wiki/Max_Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Wikiquote – Planck 1949</a></div>\\n\\n<h2>What Newspapers Wrote Then?</h2>\\n<div class=\\"qpedia-newspaper\\">\\n📰 German Physical Society — 14 Dec 1900: “Herr Planck reports on the law of energy distribution.” This short report was later published in Annalen der Physik 1901 as “On the law of distribution of energy in the normal spectrum” and is today recognized as the birth certificate of quantum physics.\\n</div>\\n<div class=\\"qpedia-para-source\\">Source: <a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – Annalen</a></div>\\n\\n<h2>Reflection Today</h2>\\n<div class=\\"qpedia-media\\">\\n🔬 When SI was redefined in 2019, kilogram was no longer defined by a metal cylinder, but by Planck constant h. That means from then on, every scale in world indirectly works with Planck’s 1900 discovery. This may be his greatest practical legacy: turning a laboratory constant into a basis for measuring the world.\\n</div>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA – SI 2019 redefinition</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Max Planck Society – legacy</a></div>\\n\\n<h2>Legacy in Your Pocket</h2>\\n<p>If you use your phone today, you owe Planck. Transistor that is heart of phone cannot be explained without quantum, laser that builds fiber-optic internet uses quantized transitions first described by Planck, and atomic clock that makes GPS accurate works with frequencies that are multiples of h. Even infrared medical thermometers and climate models predicting global warming use Planck’s radiation law. Max Planck Society today with 83 institutes in Germany and world continues same spirit of “science for knowledge” that Planck devoted his life to.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/science/Plancks-constant\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – applications</a> | <a href=\\"https://www.mpg.de/en\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG – 83 institutes</a></div>\\n\\n<h2>Exact Timeline</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>Date</th><th>Event</th></tr>\\n<tr><td>1858-04-23</td><td>Birth in Kiel, Germany</td></tr>\\n<tr><td>1874</td><td>Entered University of Munich</td></tr>\\n<tr><td>1879-07</td><td>Doctorate at 21, second law of thermodynamics</td></tr>\\n<tr><td>1889</td><td>Professor Berlin, successor Kirchhoff</td></tr>\\n<tr><td>1900-12-14</td><td>Introduced energy quantum E=hν at German Physical Society</td></tr>\\n<tr><td>1918</td><td>Nobel Prize Physics</td></tr>\\n<tr><td>1933</td><td>Meeting with Hitler to defend Jewish scientists</td></tr>\\n<tr><td>1945-01-23</td><td>Son Erwin executed for 20 July plot</td></tr>\\n<tr><td>1947-10-04</td><td>Death in Göttingen</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – timeline</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918 timeline</a> | <a href=\\"https://historydraft.com/story/max-planck/erwin-his-son-was-hanged/304/1909\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Historydraft – Erwin 1945</a></div>\\n\\n<h2>Four Common Misunderstandings</h2>\\n<p><strong>1. Planck loved quantum from start.</strong> No, he called it “act of desperation” and for years hoped to return it to classical physics. It was Einstein who took quantum seriously.</p>\\n<p><strong>2. Planck was anti-religious.</strong> No, he was church elder and believed religion and science complement, but did not believe in personal God.</p>\\n<p><strong>3. Collaborated with Nazis.</strong> No, he stayed to protect scientific institutions, met Hitler for Jews and was rejected, and resigned 1937.</p>\\n<p><strong>4. Measured Planck constant precisely.</strong> Initial value was approximate; exact modern value comes from SI definition 2019.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962</a> | <a href=\\"https://www.archiv-berlin.mpg.de/201046/Max-Planck-und-ein-zweifelhaftes-Zitat\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">MPG Archive</a> | <a href=\\"https://www.cantorsparadise.com/the-personal-tragedies-of-max-planck-490ef4246ee5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Cantor</a> | <a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA</a></div>\\n\\n<h2>Summary: Man Who Saw World in Packets</h2>\\n<p>Max Planck was born 23 April 1858 in Kiel, split physics with a seemingly small assumption on 14 December 1900, won Nobel 1918, stayed in Germany’s hardest years to defend science, lost four children and his house, and died 4 October 1947 in Göttingen. His small constant h today lives in every chip, every laser, every atomic clock, reminding us that sometimes biggest revolutions come from most conservative minds.</p>\\n<div class=\\"qpedia-para-source\\">Sources: <a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – overview</a> | <a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel 1918</a></div>\\n\\n<h2>FAQ</h2>\\n<div class=\\"qpedia-faq\\" dir=\\"ltr\\">\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Who was Max Planck?</div><div dir=\\"ltr\\">German physicist who on 14 Dec 1900 introduced energy quantum E=hν, known as father of quantum physics and Nobel 1918 winner.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">What is Planck constant?</div><div dir=\\"ltr\\">h = 6.62607015×10⁻³⁴ J·s, smallest possible action, exactly defined since 2019 and basis for kilogram definition.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Was Planck religious?</div><div dir=\\"ltr\\">Lutheran and church elder, but in 1947 letter wrote he does not believe in personal God; historians see him as deist.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">What tragedies did he experience?</div><div dir=\\"ltr\\">First wife 1909, son Karl 1916 Verdun, daughters Grete 1917 and Emma 1919 childbirth, son Erwin 1945 executed by Nazis.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">What is his legacy today?</div><div dir=\\"ltr\\">Max Planck Society with 83 institutes and basis for all quantum technology from transistor to GPS and MRI.</div></div>\\n</div>\\n\\n<h2>Sources & Further Reading</h2>\\n<ol>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1918/planck/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Max Planck biographical 1918</a></li>\\n<li><a href=\\"https://www.britannica.com/biography/Max-Planck\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Max Planck biography</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19013090310\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Planck 1901 – Annalen der Physik</a></li>\\n<li><a href=\\"https://plato.stanford.edu/entries/planck/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Max Planck</a></li>\\n<li><a href=\\"https://physics.nist.gov/cuu/Constants/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CODATA – Planck constant exact 2019</a></li>\\n<li><a href=\\"https://doi.org/10.1103/RevModPhys.34.1\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Klein 1962 – Max Planck and beginnings of quantum theory</a></li>\\n</ol>\\n\\n<div class=\\"qpedia-internal\\">\\n<strong>Read more on Qpedia:</strong> <a href=\\"https://qpedia.ir/en/what-is-quantum/\\">What is quantum</a> | <a href=\\"https://qpedia.ir/en/ultraviolet-catastrophe/\\">Ultraviolet catastrophe</a> | <a href=\\"https://qpedia.ir/en/planck-constant/\\">Planck constant</a> | <a href=\\"https://qpedia.ir/en/scientists/albert-einstein/\\">Albert Einstein</a> | <a href=\\"https://qpedia.ir/en/scientists/niels-bohr/\\">Niels Bohr</a>\\n</div>\\n\\n<script type=\\"application/ld+json\\">\\n{\\n  \\"@context\\":\\"https://schema.org\\",\\n  \\"@graph\\":[\\n    {\\"@type\\":\\"Person\\",\\"@id\\":\\"https://qpedia.ir/scientists/max-planck/#person\\",\\"name\\":\\"Max Planck\\",\\"alternateName\\":\\"ماکس پلانک\\",\\"birthDate\\":\\"1858-04-23\\",\\"deathDate\\":\\"1947-10-04\\",\\"birthPlace\\":{\\"@type\\":\\"Place\\",\\"name\\":\\"Kiel, Germany\\"},\\"nationality\\":\\"German\\",\\"award\\":[\\"Nobel Prize in Physics 19